'use strict';

module.exports = function split(line) {
  return line.split(',');
};

'use strict';

const target = require('../index');

test('splits quoted fields', () => {
  expect(target('a,"b,c"')).toEqual(['a', 'b,c']);
});

test('splits plain fields', () => {
  expect(target('a,b')).toEqual(['a', 'b']);
});
